'use strict';
(()=>{
 const G=JustinGame,P=G.Progression,game=window.justinClicker,$=id=>document.getElementById(id);
 const button=document.createElement('button');button.id='mystery-box-open';button.type='button';button.innerHTML='<img class="ui-icon" src="assets/icons/gift.svg" alt=""><span>Mystery box</span>';
 document.querySelector('.reward-dock').insertBefore(button,$('backdrops-open'));
 const dialog=document.createElement('dialog');dialog.id='roll-dialog';dialog.className='online-dialog roll-dialog';dialog.innerHTML='<div class="online-dialog-head"><h2 id="roll-title">Mystery box</h2><button id="roll-close" aria-label="Close mystery box">×</button></div><p id="roll-caption"></p><div class="roll-window" id="roll-window" aria-hidden="true" hidden><span class="roll-marker" aria-hidden="true"></span><div id="roll-track"></div></div><div id="box-cover"><img src="assets/icons/gift.svg" alt="Mystery box"></div><div id="roll-result" role="status" aria-live="polite"></div><p id="roll-odds"></p><button id="roll-action" type="button"></button>';document.body.append(dialog);
 let active=null,animation=null,waitingUntil=0,resultVisible=false,showingOffer=false,seen=new Set();
 const key=()=> 'justin-roll-seen-'+(window.justinOnline?.user()?.id||'guest');
 function remember(id){seen.add(id);try{let previous=[];try{previous=JSON.parse(localStorage.getItem(key())||'[]')}catch{}if(!Array.isArray(previous))previous=[];localStorage.setItem(key(),JSON.stringify([...new Set([...previous,id])].slice(-20)))}catch{}}
 function alreadySeen(id){try{return seen.has(id)||(localStorage.getItem(key())===id||JSON.parse(localStorage.getItem(key())||'[]').includes(id))}catch{return seen.has(id)}}
 const odds=kind=>kind==='milestone'?'Golden 20% · Platinum 35% · Diamond 15% · Points 30%':'Platinum 40% · Diamond 15% · Rainbow 5% · Gold 10% · Points 30%';
 function offer(){active=null;showingOffer=true;resultVisible=false;waitingUntil=0;$('roll-title').textContent='Mystery box';$('roll-window').hidden=true;$('box-cover').hidden=false;$('roll-result').replaceChildren();$('roll-odds').textContent=odds('box');$('roll-close').hidden=false;dialog.showModal();refreshOffer()}
 function refreshOffer(){const s=game.snapshot(),p=P.prepare(s),left=P.boxDailyLimit-p.boxesToday;$('roll-caption').textContent=left+' / '+P.boxDailyLimit+' boxes left today · duplicate variants give points';const ready=!waitingUntil&&s.bank>=P.boxCost&&left>0&&(!game.ranked()||window.justinOnline.connected());$('roll-action').disabled=!ready;$('roll-action').textContent=waitingUntil?'Opening…':left<=0?'Come back tomorrow':'Open · '+P.boxCost.toLocaleString()+' points'}
 button.onclick=offer;
 function close(){if(active&&!resultVisible){reveal();return}dialog.close();active=null;showingOffer=false;waitingUntil=0}
 $('roll-close').onclick=close;dialog.addEventListener('cancel',e=>{if(active&&!resultVisible){e.preventDefault();reveal()}else{active=null;showingOffer=false;waitingUntil=0}});
 $('roll-action').onclick=()=>{if(active){close();return}waitingUntil=Date.now()+11000;refreshOffer();game.featureAction('mystery-box')};
 function card(skinId){const card=document.createElement('div');card.className='roll-card enchanted-item';card.dataset.skin=skinId||'points';const img=document.createElement('img'),skin=G.skins.find(x=>x.id===skinId);img.alt='';if(skin){img.src=window.JustinSprites?.url(skin)||'assets/friend.png';card.append(img,document.createTextNode(skin.name))}else{img.src='assets/icons/coin.svg';card.append(img,document.createTextNode('Points'))}return card}
 function start(roll){active=roll;showingOffer=false;waitingUntil=0;resultVisible=false;if(!dialog.open)dialog.showModal();$('roll-title').textContent=roll.kind==='milestone'?roll.milestone.toLocaleString()+' clicks':'Mystery box';$('roll-caption').textContent='Rolling…';$('roll-close').hidden=false;$('roll-close').textContent='Skip';$('box-cover').hidden=true;$('roll-window').hidden=false;$('roll-result').replaceChildren();$('roll-odds').textContent=odds(roll.kind);$('roll-action').disabled=true;$('roll-action').textContent='Rolling…';const track=$('roll-track');track.replaceChildren();const pool=roll.kind==='milestone'?['platinum','lucky-gold','diamond',null]:['platinum','diamond','rainbow','gold',null];for(let i=0;i<23;i++)track.append(card(i===19?roll.skin:pool[Math.floor(Math.random()*pool.length)]));
  if($('gentle').checked||matchMedia('(prefers-reduced-motion:reduce)').matches){reveal();return}
  const end=$('roll-window').clientWidth/2-62-19*134;animation=track.animate([{transform:'translateX(0)'},{transform:'translateX('+end+'px)'}],{duration:3100,easing:'cubic-bezier(.10,.74,.14,1)',fill:'forwards'});animation.finished.then(()=>{if(active?.id===roll.id)reveal()}).catch(()=>{});
 }
 function reveal(){if(!active||resultVisible)return;resultVisible=true;if(animation){animation.cancel();animation=null}const result=$('roll-result');result.replaceChildren();result.append(card(active.skin));const text=document.createElement('p');text.textContent=active.skin?(active.fresh?'Unlocked · ':'Duplicate · ')+G.skins.find(x=>x.id===active.skin).name+' · '+G.skins.find(x=>x.id===active.skin).power+' / click':'Points';const amount=document.createElement('strong');amount.textContent='+'+active.amount.toLocaleString()+' points';result.append(text,amount);$('roll-window').hidden=true;$('roll-caption').textContent='Result';$('roll-action').disabled=false;$('roll-action').textContent='Continue';$('roll-close').textContent='×';remember(active.id);window.JustinGUIAudio?.play(active.skin?(active.fresh?'rare':'duplicate'):'reward');if(!$('gentle').checked){for(let i=0;i<12;i++){const spark=document.createElement('span');spark.className='roll-spark';spark.setAttribute('aria-hidden','true');spark.textContent=i%2?'✦':'•';spark.style.setProperty('--sx',Math.cos(i*Math.PI/6)*145+'px');spark.style.setProperty('--sy',Math.sin(i*Math.PI/6)*100+'px');spark.style.color=['#cfa53a','#9c78d1','#69c1d7'][i%3];result.append(spark);setTimeout(()=>spark.remove(),900)}}if(!$('gentle').checked)result.animate([{transform:'scale(.8)',opacity:0},{transform:'scale(1.04)',opacity:1},{transform:'scale(1)'}],{duration:400});}
 function check(){if(document.hidden||(typeof faceReady!=='undefined'&&!faceReady))return;const s=game.snapshot(),roll=(s.rollQueue||[]).find(r=>!alreadySeen(r.id))||s.lastRoll;if(active&&dialog.open)return;if(roll&&!alreadySeen(roll.id)&&active?.id!==roll.id){const other=[...document.querySelectorAll('dialog[open]')].some(d=>d!==dialog);if(!other)start(roll)}if(showingOffer&&dialog.open){if(waitingUntil&&Date.now()>waitingUntil){waitingUntil=0;$('roll-result').textContent='Could not open. Check your points or connection.'}refreshOffer()}}
 setInterval(check,300);check();
})();
